// SQL migrations generated by Prisma; transaction/checksum runner for environments
// where Prisma's experimental migration adapter cannot deserialize pg_catalog.name.
import pg from 'pg';import {readdirSync,readFileSync} from 'node:fs';import {createHash} from 'node:crypto';
const client=new pg.Client({connectionString:process.env.DATABASE_URL});await client.connect();
try{await client.query('BEGIN');await client.query("SELECT pg_advisory_xact_lock(470012)");await client.query('CREATE TABLE IF NOT EXISTS "waas_migrations" (name TEXT PRIMARY KEY, checksum TEXT NOT NULL, applied_at TIMESTAMPTZ NOT NULL DEFAULT now())');
for(const name of readdirSync('packages/db/prisma/migrations').filter(n=>/^\d/.test(n)).sort()){const sql=readFileSync(`packages/db/prisma/migrations/${name}/migration.sql`,'utf8');if(!sql.trim())throw new Error(`Empty migration: ${name}`);const checksum=createHash('sha256').update(sql).digest('hex');const {rows}=await client.query('SELECT checksum FROM "waas_migrations" WHERE name=$1',[name]);if(rows.length){if(rows[0].checksum!==checksum)throw new Error(`Migration changed: ${name}`);continue;}await client.query(sql);await client.query('INSERT INTO "waas_migrations" (name,checksum) VALUES ($1,$2)',[name,checksum]);console.log(`Applied ${name}`);}await client.query('COMMIT');}catch(e){await client.query('ROLLBACK');throw e;}finally{await client.end();}
